package local

import (
	"fmt"
	"log"
	"os"
	"os/user"
	"path/filepath"
	"reflect"

	"github.com/golang/protobuf/proto"
	"github.com/spf13/cobra"
	"google.golang.org/protobuf/encoding/prototext"
	"google.golang.org/protobuf/reflect/protoreflect"
	"knative.dev/test-infra/rundk/interactive"
)

// RunImageFromPb takes a TaaA protobuf and an image and will create and run
// a docker container of the given TaaA image on the current machine.
func RunImageFromPb(pb proto.Message, imagePath string, cleanTmp bool) error {
	b, err := proto.Marshal(pb)
	if err != nil {
		return fmt.Errorf("cannot parse proto %#v, got error %v\n", pb, err)
	}

	// Write Proto as a binary into a temporary file to mount it into the image
	tmpProtoFile, err := os.CreateTemp("/tmp/", "taaa.*.proto")
	if err != nil {
		return fmt.Errorf("failed creating tmp proto binary, got error %v\n", err)
	}
	log.Println("Created file for protobuf binary: ", tmpProtoFile.Name())
	if cleanTmp {
		defer os.Remove(tmpProtoFile.Name())
	} else {
		log.Println("The created protobuf binary file will NOT be removed post run.")
	}
	if _, err := tmpProtoFile.Write(b); err != nil {
		return fmt.Errorf("cannot write proto to file %q, got error %v\n", tmpProtoFile.Name(), err)
	}

	// Launch TaaA image with mounted proto binary in a scratch space.
	cmd := interactive.Docker{
		Command: interactive.NewCommand("docker", "run", "--rm"),
	}
	cmd.AddMount("bind", tmpProtoFile.Name(), TaaAProtoImagePath, "readonly")

	usr, err := user.Current()
	if err != nil {
		return err
	}
	const internalOutDir = "/tmp/artifacts"
	if !cleanTmp {
		outDir, err := os.MkdirTemp("", "imageoutput")
		if err != nil {
			return fmt.Errorf("Failed to make directory for image output: %s", err)
		}
		log.Println("Created temporary directory with the output files generated by the image: ", outDir)
		cmd.AddMount("bind", outDir, internalOutDir)

		f, err := os.CreateTemp("", "localrun_output.*.log")
		if err != nil {
			return fmt.Errorf("Failed to make logfile storing log output of running image: %s", err)
		}
		cmd.LogFile = f.Name()
		f.Close()
		log.Println("Created logfile storing log output of running image: ", cmd.LogFile)
	}
	// Bind in current user's configurations into the image.
	// NOTE: Do not mount readonly, apparently things write stuff here, so use overlay.
	cmd.AddRWOverlay(filepath.Join(usr.HomeDir, ".config", "gcloud"), "/root/.config/gcloud")
	cmd.AddRWOverlay(filepath.Join(usr.HomeDir, ".docker"), "/root/.docker")
	cmd.AddArgs(imagePath)
	cmd.AddArgs("run", "--output-directory", internalOutDir, "--proto", TaaAProtoImagePath)
	log.Println("Running container for image ", imagePath)
	err = cmd.Run()

	if cleanTmp {
		log.Println("Container run exited.")
	} else {
		log.Printf("Container run exited, refer to %q to see all the output of the run.", cmd.LogFile)
	}
	if err != nil {
		return fmt.Errorf("running test %q, got error %v\n", cmd, err)
	}
	return nil
}

// NewLocalRun creates a new Cobra CLI command to run a TaaA image locally.
// protoInstance needs to assigned to a pointer of an empty concrete instance of a protobuf before the returned command is executed.
func NewLocalRun(protoInstance interface{}, defaultImagePath string) *cobra.Command {
	runLocalCmd := &cobra.Command{
		Use:   "localrun",
		Short: "Run a TaaA image locally.",
		Long:  "Given a TaaA image and a textpb file, the TaaA image is run via Docker on the current machine with the given textpb file used to configure it and bound with the current user's configurations.",
		Args:  cobra.NoArgs,
	}

	imagePath := runLocalCmd.Flags().StringP("image", "i", defaultImagePath, "The docker image to run.")

	textProto := runLocalCmd.Flags().StringP("textpb", "t", "", "The path to the textpb file to pass bind into the image.")
	runLocalCmd.MarkFlagRequired("textpb")

	cleanTmp := runLocalCmd.Flags().BoolP("clean", "c", false, "If provided, then the binary proto and image output directory are deleted post run.")

	runLocalCmd.Run = func(_ *cobra.Command, _ []string) {
		protoTxtContent, err := os.ReadFile(*textProto)
		if err != nil {
			log.Fatalln("Failed to read provided textpb ", *textProto)
		}
		if protoInstance == nil || reflect.ValueOf(protoInstance).IsNil() {
			log.Fatalln("Memory for protobuf instance storing parsed textpb was not allocated before execution. Make sure the protoInstance passed to localrun.NewLocalRun is assigned to an empty instance of a protobuf type.")
		}
		pbForUnmarshal, isProtoReflect := protoInstance.(protoreflect.ProtoMessage)
		pbForWrite, isProtoMessage := protoInstance.(proto.Message)
		if !isProtoReflect || !isProtoMessage {
			log.Fatalln("Memory allocated for the protobuf instance storing the parsed textpb was malformed. Make sure protoInstance passed to localrun.NewLocalRun is a proper protobuf type.")
		}
		if err = prototext.Unmarshal(protoTxtContent, pbForUnmarshal); err != nil {
			log.Fatalf("Failed to unmarshal protobuf from %q, with error: %s", *textProto, err)
		}
		err = RunImageFromPb(pbForWrite, *imagePath, *cleanTmp)
		if err != nil {
			log.Fatalln("Failed to run image, received error: ", err)
		}
	}
	return runLocalCmd
}
